    pub palette: [(&'static str, &'static str); 8],
}

/// Tema claro (padrão).
pub const PAPER: Theme = Theme {
    name: "paper",
    canvas: "#ffffff",
    ink: "#1e1e1e",
    muted: "#5c5c5c",
    palette: [
