//! Despacho dos verbos e tradução de erro em exit code.

use crate::adapters::StdFs;
use crate::cli::{CheckArgs, Cli, Command, FmtArgs};
use crate::commands::check::CheckOutcome;
use crate::commands::fmt::{Action, FmtOutcome};
use crate::commands::{self, diagnostics_json};
use crate::envelope::Envelope;
use crate::output;
use akribie_core::Error;
use akribie_core::error::Result;
use std::process::ExitCode;

/// Forma de saída escolhida por `--json`.
#[derive(Debug, Clone, Copy)]
enum Mode {
    /// Envelope JSON de uma linha.
    Json,
    /// Texto para consumo humano e para pipe.
    Text,
}

/// Executa o subcomando escolhido.
pub(crate) fn run(cli: Cli) -> ExitCode {
    match cli.command {
        Command::Check(args) => check(&args),
        Command::Fmt(args) => fmt(&args),
        Command::Schema => schema(),
    }
}

fn check(args: &CheckArgs) -> ExitCode {
    let fs = StdFs;
    let mode = if args.json { Mode::Json } else { Mode::Text };
    match commands::check::execute(args, &fs) {
        Ok(outcome) => emit_outcome(&outcome, mode)
            .map_or_else(|error| fail(mode, "check", &error), ExitCode::from),
        Err(error) => fail(mode, "check", &error),
    }
}

fn fmt(args: &FmtArgs) -> ExitCode {
    let fs = StdFs;
    match commands::fmt::execute(args, &fs) {
        Ok(outcome) => emit_fmt(&outcome),
        Err(error) => fail(Mode::Text, "fmt", &error),
    }
}

fn emit_fmt(outcome: &FmtOutcome) -> ExitCode {
    match &outcome.action {
        Action::Emit(text) => emit_text(text, 0, "fmt"),
        Action::Check {
            formatted,
            original,
        } if formatted == original => ExitCode::SUCCESS,
        Action::Check { .. } => {
            output::warn_line(&format!("{} não está na forma canônica", outcome.file));
            ExitCode::from(1)
