//!
//! Uma linha, `\n` final, campos opcionais omitidos quando ausentes: `data` e `error` nunca
//! aparecem como `null`, e `warnings` aparece sempre (lista vazia quando não há).

use crate::commands::diagnostics_json;
use akribie_core::Error;
use akribie_core::diag::Diagnostic;
use serde::Serialize;
use serde_json::Value;

/// Corpo de erro do envelope.
#[derive(Debug, Serialize)]
pub(crate) struct ErrorBody {
    /// Código textual (`invalid_input`, `not_found`, `io`, `schema`, `internal`).
    pub(crate) code: &'static str,
    /// Mensagem auto-suficiente.
    pub(crate) message: String,
}

/// Envelope `{success, command, data?, error?, warnings}`.
#[derive(Debug, Serialize)]
pub(crate) struct Envelope {
    /// `true` quando o comando concluiu sem erro.
    pub(crate) success: bool,
    /// Nome do verbo (`check`, `render`, …).
    pub(crate) command: &'static str,
    /// Payload do verbo, quando houver.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub(crate) data: Option<Value>,
    /// Erro, quando houver.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub(crate) error: Option<ErrorBody>,
    /// Avisos no formato `"<code>: <message>"`.
    pub(crate) warnings: Vec<String>,
}

impl Envelope {
    /// Sucesso com payload.
    pub(crate) fn ok(command: &'static str, data: Value) -> Self {
        Self {
            success: true,
            command,
            data: Some(data),
            error: None,
            warnings: Vec::new(),
        }
    }

    /// Falha de processo (sem payload).
        }
        Action::Written => ExitCode::SUCCESS,
        Action::Failed => emit_text(
            &commands::render_diagnostics(&outcome.file, &outcome.diagnostics),
            8,
            "fmt",
        ),
    }
}

fn emit_text(text: &str, code: u8, command: &'static str) -> ExitCode {
    match output::emit(text, code) {
        Ok(exit) => ExitCode::from(exit),
        Err(error) => fail(Mode::Text, command, &error),
    }
}

fn schema() -> ExitCode {
    match output::write_stdout(&commands::schema::render()) {
        Ok(_) => ExitCode::SUCCESS,
        Err(error) => fail(Mode::Text, "schema", &error),
    }
}

fn emit_outcome(outcome: &CheckOutcome, mode: Mode) -> Result<u8> {
    let code = if outcome.failed() { 8 } else { 0 };
    if let Mode::Json = mode {
        let rendered = if outcome.failed() {
            let error = Error::schema(format!("{} (ver diagnósticos)", outcome.summary()));
            Envelope::failed_with_diagnostics("check", &error, &outcome.diagnostics)
        } else {
            Envelope::ok("check", diagnostics_json(&outcome.diagnostics))
        };
        output::emit(&rendered.render(), code)
    } else {
        output::emit(
            &commands::render_diagnostics(&outcome.file, &outcome.diagnostics),
            code,
        )
    }
}

fn fail(mode: Mode, command: &'static str, error: &Error) -> ExitCode {
    let code = error.exit_code();
    if let Mode::Json = mode {
        match output::write_stdout(&Envelope::failed(command, error).render()) {
            Ok(true) | Err(_) => ExitCode::from(code),
            Ok(false) => ExitCode::SUCCESS,
        }
    } else {
        output::error_line(error.message());
        ExitCode::from(code)
    }
}

