fn rgb(pixmap: &tiny_skia::Pixmap) -> Vec<u8> {
    let data = pixmap.data();
    let mut rgb = Vec::with_capacity(data.len() / 4 * 3);
    for pixel in data.chunks_exact(4) {
        if let [red, green, blue, _] = pixel {
            rgb.extend_from_slice(&[*red, *green, *blue]);
        }
    }
    rgb
