/// Segmento de reta com o traço duplo.
pub fn line(from: Point, to: Point, seed: u32) -> String {
    two_passes(seed, |rng| {
        let a = jitter(rng, from, MAX_OFFSET * 0.5);
        let b = jitter(rng, to, MAX_OFFSET * 0.5);
        format!("{} {}", moveto(a), lineto(b))
    })
}

