/// Zigue-zague horizontal cobrindo o retângulo.
pub fn zigzag(rect: Rect, amplitude: f32, step: f32) -> String {
    if step <= 0.5 {
        return String::new();
    }
    let mut segments: Vec<String> = Vec::new();
    let mut y = rect.y + step * 0.5;
    while y < rect.bottom() {
        segments.push(format!(
            "{} {} {}",
            moveto((rect.x, y - amplitude)),
            lineto((rect.x + rect.w * 0.5, y + amplitude)),
            lineto((rect.right(), y - amplitude))
        ));
        y += step;
    }
    segments.join(" ")
}

fn clamp_to_rect(point: Point, rect: Rect) -> Point {
    (
        point.0.clamp(rect.x, rect.right()),
        point.1.clamp(rect.y, rect.bottom()),
    )
}

/// Cabeça de seta preenchida, apontando de `back` para `tip`.
pub fn arrow_head(tip: Point, back: Point) -> String {
    const LEN: f32 = 12.0;
    const WIDE: f32 = 8.0;
    let dx = tip.0 - back.0;
    let dy = tip.1 - back.1;
    let length = (dx * dx + dy * dy).sqrt();
    if length < f32::EPSILON {
        return String::new();
    }
    let ux = dx / length;
    let uy = dy / length;
    let base = (tip.0 - ux * LEN, tip.1 - uy * LEN);
    let left = (base.0 - uy * WIDE, base.1 + ux * WIDE);
    let right = (base.0 + uy * WIDE, base.1 - ux * WIDE);
    format!("{} {} {} Z", moveto(tip), lineto(left), lineto(right))
}

