fn generators_are_identical_for_the_same_seed() {
    let frame = Rect::new(0.0, 0.0, 100.0, 40.0);
    assert_eq!(rect(frame, 12.0, 42), rect(frame, 12.0, 42));
    assert_eq!(ellipse(frame, 42), ellipse(frame, 42));
    assert_ne!(rect(frame, 12.0, 42), rect(frame, 12.0, 43));
