//! Diff semântico entre dois documentos resolvidos.
//!
//! Compara o `.akrc` resolvido — topologia, rótulos e estilo —, nunca geometria: o layout é
//! derivado e muda sem mudança de intenção. Identidade: `node`/`group` por `id`, `edge` por
//! `(from, to, ordinal)` e `note` por `near` + posição entre as notas da mesma âncora (a gramática
//! não dá id a nota). O resultado é ordenado por id e agrupado na ordem `added`, `removed`,
//! `changed` (ADR-0002).

use std::collections::BTreeMap;

use crate::model::{Chart, Edge, Group, Node, Note};
use crate::num;

/// Tipo de mudança.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Kind {
    /// Elemento que só existe no documento novo.
    Added,
    /// Elemento que só existe no documento antigo.
    Removed,
    /// Elemento presente nos dois, com ao menos um campo diferente.
    Changed,
}

/// Uma mudança semântica.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Change {
    /// Adição, remoção ou alteração.
    pub kind: Kind,
    /// Descrição do elemento (`node api "API"`, `edge api->db#0`).
    pub element: String,
    /// Campo alterado (só em [`Kind::Changed`]).
    pub field: Option<&'static str>,
    /// Valor no documento antigo.
    pub before: Option<String>,
    /// Valor no documento novo.
    pub after: Option<String>,
}

impl Change {
    /// Linha de texto: `+ node dlq "DLQ"`, `- node legacy`, `~ node a shape: rect -> rounded`.
    pub fn line(&self) -> String {
        match self.kind {
            Kind::Added => format!("+ {}", self.element),
            Kind::Removed => format!("- {}", self.element),
            Kind::Changed => format!(
                "~ {} {}: {} -> {}",
                self.element,
                self.field.unwrap_or("?"),
                self.before.as_deref().unwrap_or(""),
                self.after.as_deref().unwrap_or("")
            ),
        }
    }
}

/// Compara dois documentos resolvidos.
pub fn diff(old: &Chart, new: &Chart) -> Vec<Change> {
    let mut added = Vec::new();
    let mut removed = Vec::new();
    let mut changed = Vec::new();

    chart_changes(old, new, &mut changed);

    compare(
        old.groups.as_slice(),
        new.groups.as_slice(),
        |group| group.id.clone(),
        group_text,
        group_fields,
        &mut added,
        &mut removed,
        &mut changed,
    );
    compare(
        old.nodes.as_slice(),
        new.nodes.as_slice(),
        |node| node.id.clone(),
        node_text,
        node_fields,
        &mut added,
        &mut removed,
        &mut changed,
    );
    let mut old_edges = keyed_edges(&old.edges);
    let mut new_edges = keyed_edges(&new.edges);
    old_edges.sort_by(|left, right| left.0.cmp(&right.0));
    new_edges.sort_by(|left, right| left.0.cmp(&right.0));
    compare_edges(&old_edges, &new_edges, &mut added, &mut removed, &mut changed);
    let mut old_notes = keyed_notes(&old.notes);
    let mut new_notes = keyed_notes(&new.notes);
    old_notes.sort_by(|left, right| left.0.cmp(&right.0));
    new_notes.sort_by(|left, right| left.0.cmp(&right.0));
    compare_notes(
        &old_notes,
        &new_notes,
        &mut added,
        &mut removed,
        &mut changed,
    );

    added.sort_by(|left, right| left.element.cmp(&right.element));
    removed.sort_by(|left, right| left.element.cmp(&right.element));
    changed.sort_by(|left, right| {
        left.element
            .cmp(&right.element)
            .then_with(|| left.field.cmp(&right.field))
    });
    added
        .into_iter()
        .chain(removed)
        .chain(changed)
        .collect()
}

fn chart_changes(old: &Chart, new: &Chart, out: &mut Vec<Change>) {
    let fields = [
        ("title", option_text(old.title.as_deref()), option_text(new.title.as_deref())),
        ("layout", old.layout.name().to_string(), new.layout.name().to_string()),
        ("direction", old.direction.name().to_string(), new.direction.name().to_string()),
        ("theme", old.theme.name.to_string(), new.theme.name.to_string()),
        ("fontsize", num::format(old.fontsize), num::format(new.fontsize)),
        ("pad", num::format(old.pad), num::format(new.pad)),
        ("lang", old.lang.clone(), new.lang.clone()),
        ("doc", option_text(old.doc.as_deref()), option_text(new.doc.as_deref())),
    ];
    for (field, before, after) in fields {
        if before != after {
            out.push(Change {
                kind: Kind::Changed,
                element: "chart".to_string(),
                field: Some(field),
                before: Some(before),
                after: Some(after),
            });
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn compare<T>(
    old: &[T],
    new: &[T],
    key: impl Fn(&T) -> String,
    describe: impl Fn(&T) -> String,
    fields: impl Fn(&T) -> Vec<(&'static str, String)>,
    added: &mut Vec<Change>,
    removed: &mut Vec<Change>,
    changed: &mut Vec<Change>,
) {
    let index = |items: &[T]| -> BTreeMap<String, &T> {
        items.iter().map(|item| (key(item), item)).collect()
    };
    let mut old_index = index(old);
    let new_index = index(new);
    old_index.extend(new_index.iter().map(|(k, v)| (k.clone(), *v)));
    for (id, item) in &old_index {
        match (old_index.get(id).filter(|_| old.iter().any(|cand| key(cand) == *id)), new_index.get(id)) {
            _ => {}
        }
    }
    let old_map = index(old);
    let new_map = index(new);
    let mut keys: Vec<&String> = old_map.keys().chain(new_map.keys()).collect();
    keys.sort();
    keys.dedup();
    for id in keys {
        match (old_map.get(id), new_map.get(id)) {
            (Some(left), Some(right)) => {
                let before = fields(left);
                let after = fields(right);
                for ((field, old_value), (_, new_value)) in before.iter().zip(after.iter()) {
                    if old_value != new_value {
                        changed.push(Change {
                            kind: Kind::Changed,
                            element: describe(right),
                            field: Some(field),
                            before: Some(old_value.clone()),
                            after: Some(new_value.clone()),
                        });
                    }
                }
            }
            (Some(left), None) => removed.push(Change {
                kind: Kind::Removed,
                element: describe(left),
                field: None,
                before: None,
                after: None,
            }),
            (None, Some(right)) => added.push(Change {
                kind: Kind::Added,
                element: describe(right),
                field: None,
                before: None,
                after: None,
            }),
            (None, None) => {}
        }
    }
}

fn keyed_edges(edges: &[Edge]) -> Vec<(String, &Edge)> {
    edges
        .iter()
        .map(|edge| (format!("{}->{}#{}", edge.from, edge.to, edge.ordinal), edge))
        .collect()
}

fn keyed_notes(notes: &[Note]) -> Vec<(String, &Note)> {
    let mut seen: BTreeMap<String, usize> = BTreeMap::new();
    notes
        .iter()
        .map(|note| {
            let anchor = note.near.clone().unwrap_or_default();
            let index = seen.entry(anchor.clone()).or_insert(0);
            let key = format!("{anchor}#{index}");
            *index += 1;
            (key, note)
        })
        .collect()
}

fn compare_edges(
    old: &[(String, &Edge)],
    new: &[(String, &Edge)],
    added: &mut Vec<Change>,
    removed: &mut Vec<Change>,
    changed: &mut Vec<Change>,
) {
    for (id, edge) in new {
        match old.iter().find(|(key, _)| key == id) {
            Some((_, before)) => push_fields(edge_text(before), edge_fields(before), edge_fields(edge), changed),
            None => added.push(Change {
                kind: Kind::Added,
                element: edge_text(edge),
                field: None,
                before: None,
                after: None,
            }),
        }
    }
    for (id, edge) in old {
        if !new.iter().any(|(key, _)| key == id) {
            removed.push(Change {
                kind: Kind::Removed,
                element: edge_text(edge),
                field: None,
                before: None,
                after: None,
            });
        }
    }
}

fn compare_notes(
    old: &[(String, &Note)],
    new: &[(String, &Note)],
    added: &mut Vec<Change>,
    removed: &mut Vec<Change>,
    changed: &mut Vec<Change>,
) {
    for (id, note) in new {
        match old.iter().find(|(key, _)| key == id) {
            Some((_, before)) => push_fields(note_text(before), note_fields(before), note_fields(note), changed),
            None => added.push(Change {
                kind: Kind::Added,
                element: note_text(note),
                field: None,
                before: None,
                after: None,
            }),
        }
    }
    for (id, note) in old {
        if !new.iter().any(|(key, _)| key == id) {
            removed.push(Change {
                kind: Kind::Removed,
                element: note_text(note),
                field: None,
                before: None,
                after: None,
            });
        }
    }
}

fn push_fields(
    element: String,
    before: Vec<(&'static str, String)>,
    after: Vec<(&'static str, String)>,
    changed: &mut Vec<Change>,
) {
    for ((field, old_value), (_, new_value)) in before.iter().zip(after.iter()) {
        if old_value != new_value {
            changed.push(Change {
                kind: Kind::Changed,
                element: element.clone(),
                field: Some(field),
                before: Some(old_value.clone()),
                after: Some(new_value.clone()),
            });
        }
    }
}

fn node_text(node: &Node) -> String {
    format!("node {} {}", node.id, quoted(node.declared_label.as_deref()))
}

fn group_text(group: &Group) -> String {
    format!("group {} {}", group.id, quoted(group.declared_label.as_deref()))
}

fn edge_text(edge: &Edge) -> String {
    let label = edge.label.as_deref().map_or(String::new(), |label| {
        format!(" \"{label}\"")
    });
    if edge.ordinal == 0 {
        format!("edge {}->{}{label}", edge.from, edge.to)
    } else {
        format!("edge {}->{}#{}{label}", edge.from, edge.to, edge.ordinal)
    }
}

fn note_text(note: &Note) -> String {
    match &note.near {
        Some(near) => format!("note \"{}\" near={near}", one_line(&note.text)),
        None => format!("note \"{}\"", one_line(&note.text)),
    }
}

fn quoted(label: Option<&str>) -> String {
    label.map_or(String::new(), |label| format!("\"{label}\""))
}

fn one_line(text: &str) -> String {
    text.replace('\n', " ")
}

fn option_text(value: Option<&str>) -> String {
    value.unwrap_or("").to_string()
}

fn node_fields(node: &Node) -> Vec<(&'static str, String)> {
    let mut fields = vec![
        ("label", node.label.clone()),
        ("shape", node.shape.name().to_string()),
        ("fill", node.fill.name().to_string()),
        ("fillstyle", node.fillstyle.name().to_string()),
        ("stroke", node.stroke.name().to_string()),
        ("style", node.style.name().to_string()),
        ("width", num::format(node.width)),
        ("groups", node.groups.join(",")),
    ];
    if let Some((x, y)) = node.at {
        fields.push(("at", format!("{},{}", num::format(x), num::format(y))));
    }
    if let Some((w, h)) = node.size {
        fields.push(("size", format!("{},{}", num::format(w), num::format(h))));
    }
    fields
}

fn group_fields(group: &Group) -> Vec<(&'static str, String)> {
    vec![
        ("label", group.label.clone()),
        ("fill", group.fill.name().to_string()),
        ("stroke", group.stroke.name().to_string()),
        ("style", group.style.name().to_string()),
        ("width", num::format(group.width)),
        ("pad", num::format(group.pad)),
        ("groups", group.groups.join(",")),
    ]
}

fn edge_fields(edge: &Edge) -> Vec<(&'static str, String)> {
    vec![
        ("label", edge.label.clone().unwrap_or_default()),
        ("curve", edge.curve.name().to_string()),
        ("head", edge.head.name().to_string()),
        ("tail", edge.tail.name().to_string()),
        ("style", edge.style.name().to_string()),
        ("stroke", edge.stroke.name().to_string()),
        ("width", num::format(edge.width)),
    ]
}

fn note_fields(note: &Note) -> Vec<(&'static str, String)> {
    let mut fields = vec![
        ("text", one_line(&note.text)),
        ("fill", note.fill.name().to_string()),
        ("near", note.near.clone().unwrap_or_default()),
    ];
    if let Some((x, y)) = note.at {
        fields.push(("at", format!("{},{}", num::format(x), num::format(y))));
    }
    if let Some((w, h)) = note.size {
        fields.push(("size", format!("{},{}", num::format(w), num::format(h))));
    }
    fields
}

