fn fail(mode: Mode, command: &'static str, error: &Error) -> ExitCode {
    let code = error.exit_code();
    if let Mode::Json = mode {
        match output::write_stdout(&Envelope::failed(command, error).render()) {
            Ok(true) | Err(_) => ExitCode::from(code),
            Ok(false) => ExitCode::SUCCESS,
        }
    } else {
        output::error_line(error.message());
        ExitCode::from(code)
    }
