    pub(crate) warnings: Vec<String>,
}

impl Envelope {
    /// Sucesso com payload.
    pub(crate) fn ok(command: &'static str, data: Value) -> Self {
        Self {
            success: true,
            command,
            data: Some(data),
            error: None,
            warnings: Vec::new(),
        }
    }

