//! `.excalidraw` → `.akrc`.
//!
//! Mapeamento do ADR-0004: retângulo → `shape=rounded`, elipse → `circle`, losango → `diamond`,
//! texto com `containerId` → rótulo do container, texto solto → `note`, seta com os dois bindings →
//! `edge`. O resto é descartado com `W006`. A rota nunca é importada: o layout recalcula.

use serde_json::Value;

use crate::diag::{Diagnostic, W005, W006};
use crate::fmt;
use crate::parse;
use crate::span::Span;
use crate::theme::PAPER;

/// Resultado da importação.
#[derive(Debug, Clone, PartialEq)]
pub struct Imported {
    /// Fonte `.akrc` na forma canônica.
    pub source: String,
    /// Perdas anunciadas (`W005`/`W006`).
    pub diagnostics: Vec<Diagnostic>,
}

/// Converte um `.excalidraw` em `.akrc`.
///
/// # Errors
/// `InvalidInput` quando o JSON não for um objeto, não tiver `type: "excalidraw"` ou não tiver
/// `elements`.
pub fn import(input: &str, name: &str) -> crate::error::Result<Imported> {
    let value: Value = serde_json::from_str(input)
        .map_err(|error| crate::error::Error::invalid_input(format!("JSON inválido: {error}")))?;
    if value.get("type").and_then(Value::as_str) != Some("excalidraw") {
        return Err(crate::error::Error::invalid_input(
            "não é um `.excalidraw`: falta `\"type\": \"excalidraw\"`",
        ));
    }
    let elements = value
        .get("elements")
        .and_then(Value::as_array)
        .ok_or_else(|| crate::error::Error::invalid_input("`.excalidraw` sem `elements`"))?;

    let mut diagnostics = Vec::new();
    let mut names: Vec<String> = Vec::new();
    let mut shapes = String::new();
    let mut edges = String::new();
    let mut notes = String::new();
    let mut labels: Vec<(String, String)> = Vec::new();

    for element in elements {
        let kind = element.get("type").and_then(Value::as_str).unwrap_or("");
        if element
            .get("isDeleted")
            .and_then(Value::as_bool)
            .unwrap_or(false)
        {
            continue;
        }
        match kind {
            "rectangle" | "ellipse" | "diamond" => {
                let id = element_id(element, names.len() + 1);
                names.push(id.clone());
                let shape = match kind {
                    "ellipse" => "circle",
                    "diamond" => "diamond",
                    _ => "rounded",
                };
                let (fill, fill_warning) = fill_of(element, &mut diagnostics);
                let (stroke, stroke_warning) = stroke_of(element, &mut diagnostics);
                diagnostics.extend(fill_warning);
                diagnostics.extend(stroke_warning);
                let corner = format!(
                    "at={},{} size={},{}",
                    number(element, "x"),
                    number(element, "y"),
                    dimension(element, "width"),
                    dimension(element, "height")
                );
                shapes.push_str(&format!(
                    "node {id} shape={shape} fill={fill} stroke={stroke} {corner}\n"
                ));
            }
            "text" => {
                let text = element
                    .get("text")
                    .or_else(|| element.get("originalText"))
                    .and_then(Value::as_str)
                    .unwrap_or("");
                match element.get("containerId").and_then(Value::as_str) {
                    Some(container) => labels.push((container.to_string(), escape(text))),
                    None => {
                        let (fill, fill_warning) = fill_of(element, &mut diagnostics);
                        diagnostics.extend(fill_warning);
                        notes.push_str(&format!(
                            "note \"{}\" fill={fill} at={},{} size={},{}\n",
                            escape(text),
                            number(element, "x"),
                            number(element, "y"),
                            dimension(element, "width"),
                            dimension(element, "height")
                        ));
                    }
                }
            }
            "arrow" => {
                let from = element
                    .pointer("/startBinding/elementId")
                    .and_then(Value::as_str);
                let to = element
                    .pointer("/endBinding/elementId")
                    .and_then(Value::as_str);
                match (from, to) {
                    (Some(from), Some(to)) => {
                        let from = map_id(&names, from);
                        let to = map_id(&names, to);
                        edges.push_str(&format!(
                            "edge {} -> {} style={}\n",
                            from,
                            to,
                            stroke_style(element)
                        ));
                    }
                    _ => diagnostics.push(dropped(element, "seta sem bindings nos dois lados")),
                }
            }
            other => diagnostics.push(dropped(element, &format!("tipo `{other}`"))),
        }
    }

    let mut source = format!("chart v1 \"{}\" layout=free\n", escape(name));
    source.push_str(&shapes);
    source.push_str(&edges);
    source.push_str(&notes);
    // Rótulos entram depois de o container existir: reescrevemos a linha com o texto.
    for (container, label) in &labels {
        let id = map_id(&names, container);
        let needle = format!("node {id} shape=");
        if let Some(start) = source.find(&needle) {
            if let Some(end) = source[start..].find(" fill=") {
                let insert = start + end;
                source.insert_str(insert, &format!(" \"{label}\""));
            }
        }
    }
    let (document, _) = parse::parse(&source);
    Ok(Imported {
        source: fmt::format(&document),
        diagnostics,
    })
}

fn element_id(element: &Value, fallback: usize) -> String {
    element
        .get("id")
        .and_then(Value::as_str)
        .map_or_else(|| format!("n{fallback}"), |id| sanitize(id))
}

fn sanitize(id: &str) -> String {
    let mut out = String::with_capacity(id.len());
    for ch in id.chars() {
        if ch.is_ascii_alphanumeric() || ch == '_' || ch == '-' {
            out.push(ch);
        } else {
            out.push('_');
        }
    }
    if out.is_empty() || out.starts_with(|ch: char| ch.is_ascii_digit()) {
        out.insert(0, 'n');
    }
    out
}

/// Id do `.akrc` a partir do id do Excalidraw (com o mesmo `sanitize`).
fn map_id(names: &[String], external: &str) -> String {
    let wanted = sanitize(external);
    if names.contains(&wanted) {
        wanted
    } else {
        format!("n{}", names.len() + 1)
    }
}

fn fill_of(element: &Value, diagnostics: &mut Vec<Diagnostic>) -> (String, Vec<Diagnostic>) {
    color_token(element, "backgroundColor", "none", diagnostics)
}

fn stroke_of(element: &Value, diagnostics: &mut Vec<Diagnostic>) -> (String, Vec<Diagnostic>) {
    color_token(element, "strokeColor", "muted", diagnostics)
}

fn color_token(
    element: &Value,
    key: &str,
    fallback: &str,
    diagnostics: &mut Vec<Diagnostic>,
) -> (String, Vec<Diagnostic>) {
    let raw = element
        .get(key)
        .and_then(Value::as_str)
        .unwrap_or("transparent");
    if raw.eq_ignore_ascii_case("transparent") {
        return (fallback.to_string(), Vec::new());
    }
    match PAPER
        .palette
        .iter()
        .find(|(_, hex)| hex.eq_ignore_ascii_case(raw))
    {
        Some((name, _)) => ((*name).to_string(), Vec::new()),
        None => {
            let mut diagnostic = Diagnostic::new(
                W005,
                Span::new(1, 1),
                format!("cor `{raw}` sem token de tema; usando `{fallback}`"),
            );
            diagnostic.hint = Some(
                "tokens aceitos: paper, ink, muted, blue, green, amber, red, violet".to_string(),
            );
            diagnostics.push(diagnostic);
            (fallback.to_string(), Vec::new())
        }
    }
}

fn dropped(element: &Value, why: &str) -> Diagnostic {
    let id = element.get("id").and_then(Value::as_str).unwrap_or("?");
    let mut diagnostic = Diagnostic::new(
        W006,
        Span::new(1, 1),
        format!("elemento `{id}` descartado ({why})"),
    );
    diagnostic.hint =
        Some("o `.akrc` não representa imagens, frames nem agrupamentos do Excalidraw".to_string());
    diagnostic
}

fn stroke_style(element: &Value) -> &'static str {
    match element
        .get("strokeStyle")
        .and_then(Value::as_str)
        .unwrap_or("solid")
    {
        "dashed" => "dashed",
        "dotted" => "dotted",
        _ => "solid",
    }
}

fn number(element: &Value, key: &str) -> String {
    let value = element.get(key).and_then(Value::as_f64).unwrap_or(0.0);
    crate::num::format(value as f32)
}

fn dimension(element: &Value, key: &str) -> String {
    let value = element.get(key).and_then(Value::as_f64).unwrap_or(0.0);
    crate::num::format((value as f32).max(1.0))
}

fn escape(text: &str) -> String {
    text.replace('\\', "\\\\").replace('"', "\\\"")
}

