/// `akr diff FILE --at REV`: compara a revisão com a árvore de trabalho.
fn against_revision(args: &DiffArgs, fs: &dyn Fs, git: &dyn Git, rev: &str) -> Result<DiffOutcome> {
    if args.old.is_some() && args.new.is_some() {
        return Err(Error::invalid_input(
            "`--at REV` compara um arquivo com a revisão dele; informe só FILE",
        ));
    }
    let Some(file) = args.new.as_deref().or(args.old.as_deref()) else {
        return Err(Error::invalid_input("`--at REV` exige FILE"));
    };
    let path = Path::new(file);
    let old = git.show(rev, path)?;
    let new = fs.read(path)?;
    let config = Config::discover(fs, Some(path))?;
    let font = Font::load()?;
    Ok(compare_sources(
        old,
        new,
        format!("{file}@{rev}"),
        file.to_string(),
        &config,
        &font,
    ))
}

fn compare_sources(
    old_source: &str,
    new_source: &str,
    old: &str,
    new: &str,
    config: &Config,
    font: &Font,
) -> DiffOutcome {
    let old_report = pipeline::check(&old_source, config, font);
    if has_errors(&old_report.diagnostics) {
        return failed(old, old_report.diagnostics);
    }
    let new_report = pipeline::check(&new_source, config, font);
    if has_errors(&new_report.diagnostics) {
        return failed(new, new_report.diagnostics);
    }
    let mut warnings: Vec<(String, Diagnostic)> = old_report
        .diagnostics
        .into_iter()
        .map(|diagnostic| (old.clone(), diagnostic))
        .collect();
    warnings.extend(
        new_report
            .diagnostics
            .into_iter()
            .map(|diagnostic| (new.clone(), diagnostic)),
    );
    DiffOutcome {
        old,
        new,
        changes: akribie_core::diff(&old_report.chart, &new_report.chart),
        failed_file: None,
        diagnostics: Vec::new(),
        warnings,
    }
}

