            fs.write(Path::new(&path), &bytes)?;
            (None, Some(path), Some(written))
        }
    };
    let mut diagnostics = report.diagnostics;
    diag::sort(&mut diagnostics);
    Ok(RenderOutcome {
        file,
        format: format.name(),
        payload,
        written,
        bytes,
        diagnostics,
        failed: false,
    })
}

