fn check_batch(batch: &str) -> ExitCode {
    let fs = StdFs;
    match commands::check::execute_batch(batch, &fs) {
        Ok(outcomes) => {
            let mut text = String::new();
            let mut failed = false;
            for outcome in &outcomes {
                failed |= !outcome.is_ok();
                let value = match (&outcome.error, &outcome.report) {
                    (Some(error), _) => serde_json::json!({
                        "error": error,
                        "name": outcome.name,
                        "success": false,
                    }),
                    (None, Some(report)) => serde_json::json!({
                        "diagnostics": report
                            .diagnostics
                            .iter()
                            .map(Diagnostic::to_json)
                            .collect::<Vec<_>>(),
                        "name": outcome.name,
                        "success": !has_errors(&report.diagnostics),
                    }),
                    (None, None) => serde_json::json!({
                        "error": "item sem relatório",
                        "name": outcome.name,
                        "success": false,
                    }),
                };
                text.push_str(&value.to_string());
                text.push('\n');
            }
            emit_text(&text, u8::from(failed) * 8, "check")
        }
        Err(error) => fail(Mode::Json, "check", &error),
    }
