/// Tamanho de cada nó na ordem de `chart.nodes` (`size` declarado ou medição do rótulo).
fn node_sizes(chart: &Chart, font: &Font) -> Vec<(f32, f32)> {
    chart
        .nodes
        .iter()
        .map(|node| {
            node.size
                .unwrap_or_else(|| font.node_size(&node.label, chart.fontsize))
        })
        .collect()
}

/// Rótulo quebrado para a largura útil de um nó.
fn label_lines(label: &str, size: (f32, f32), fontsize: f32, font: &Font) -> Vec<String> {
    let usable = (size.0 - 2.0 * text::NODE_PADDING).max(1.0);
    font.wrap(label, fontsize, usable)
}

/// Flags de seta a partir dos `Head` do modelo.
