use crate::model::Shape;

/// Ponto no plano do canvas (origem no canto superior esquerdo, y para baixo).
pub type Point = (f32, f32);

/// Retângulo alinhado aos eixos.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Rect {
    /// Canto esquerdo.
    pub x: f32,
    /// Canto superior.
