/// Bloco `<g data-id="ID" …>…</g>` do SVG.
fn element_block(svg: &str, id: &str) -> String {
    let marker = format!("data-id=\"{id}\"");
    let start = svg.find(&marker).unwrap_or_else(|| panic!("sem {id}"));
    let end = svg[start..].find("</g>").map_or(svg.len(), |offset| start + offset);
    svg[start..end].to_string()
}

